-- saborya_finanzas.sql · Datos de facturación electrónica de SaborYa para la clase de Power BI
-- Ejecutar completo en MySQL Workbench (File > Open SQL Script, luego el rayo "Execute").
-- Las facturas corresponden a los pedidos entregados de pedidos_historico (MongoDB, script s4_historico.js):
-- facturas.numero_pedido = pedidos_historico.numero
DROP DATABASE IF EXISTS saborya_finanzas;
CREATE DATABASE saborya_finanzas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE saborya_finanzas;

CREATE TABLE comisiones (
  restaurante_id VARCHAR(5) PRIMARY KEY,
  porcentaje_comision DECIMAL(4,2) NOT NULL
);

CREATE TABLE metas_mensuales (
  ciudad VARCHAR(40) NOT NULL,
  anio SMALLINT NOT NULL,
  mes TINYINT NOT NULL,
  meta_ventas DECIMAL(14,0) NOT NULL,
  PRIMARY KEY (ciudad, anio, mes)
);

CREATE TABLE facturas (
  numero_pedido INT PRIMARY KEY,
  numero_factura VARCHAR(12) NOT NULL UNIQUE,
  fecha_emision DATETIME NOT NULL,
  base DECIMAL(12,0) NOT NULL,
  impoconsumo DECIMAL(12,0) NOT NULL,
  total DECIMAL(12,0) NOT NULL,
  estado_dian ENUM('aceptada','pendiente','rechazada') NOT NULL
);



















































































-- Verificación
SELECT COUNT(*) AS facturas FROM facturas;
SELECT estado_dian, COUNT(*) AS cantidad, SUM(total) AS total FROM facturas GROUP BY estado_dian;
SELECT COUNT(*) AS metas FROM metas_mensuales;
